import re
from taf.selenium.mobile.sbts.facade import Sbts, Sbts22R1
from taf.selenium.mobile.sbts.exceptions import InvalidSbtsVersion


class SupportedSbtss(object):
    sbts = Sbts
    sbts22r1 = Sbts22R1

    @classmethod
    def get_valid_sbts_versions(cls):
        sbts_versions = []
        for item in cls.__dict__.keys():
            if item.startswith('sbts'):
                sbts_versions.append(item)
        return sbts_versions


class Provider(object):
    @classmethod
    def provide(cls, version=None):
        regex_for_verison = "(?:[Ss][Bb][Tt][Ss])?(.*)?"
        supported_sbts = "sbts"
        if version:
            version_parsed = re.search(regex_for_verison, version).group(1)
            supported_sbts = "sbts{version}".format(version=version_parsed.lower())

        try:
            return getattr(SupportedSbtss, supported_sbts)
        except AttributeError:
            raise InvalidSbtsVersion('Supported versions: {}'.format(SupportedSbtss.get_valid_sbts_versions()))
